INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-01-01', 'lesson-survival-a2-01', 1, 'sentence', 'Sorry, I didn''t understand.', 'Desculpe, não entendi.', '/ˈsɑːri aɪ ˈdɪdənt ˌʌndərˈstænd/', 'Passado: "didn''t understand". Mais natural que "I don''t understand" depois de ouvir algo.', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"understand","pos":"verb","ipa":"/ˌʌndərˈstænd/","gloss":"entender"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-02', 'lesson-survival-a2-01', 2, 'sentence', 'Could you speak more slowly?', 'Você poderia falar mais devagar?', '/kʊd juː spiːk mɔːr ˈsloʊli/', '"More slowly" = mais devagar.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"slowly","pos":"adverb","ipa":"/ˈsloʊli/","gloss":"devagar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-03', 'lesson-survival-a2-01', 3, 'sentence', 'I''m still learning English.', 'Ainda estou aprendendo inglês.', '/aɪm stɪl ˈlɜːrnɪŋ ˈɪŋɡlɪʃ/', 'Avisa e gera paciência do outro lado.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"still","pos":"adverb","ipa":"/stɪl/","gloss":"ainda"},{"surface":"learning","pos":"verb","ipa":"/ˈlɜːrnɪŋ/","gloss":"aprendendo"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-04', 'lesson-survival-a2-01', 4, 'sentence', 'What does that mean?', 'O que isso significa?', '/wʌt dʌz ðæt miːn/', 'Pergunta sobre uma palavra.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-05', 'lesson-survival-a2-01', 5, 'sentence', 'Could you say that in another way?', 'Pode dizer de outro jeito?', '/kʊd juː seɪ ðæt ɪn əˈnʌðər weɪ/', '"In another way" = de outro jeito.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"another","pos":"determiner","ipa":"/əˈnʌðər/","gloss":"outro, mais um"},{"surface":"way","pos":"noun","ipa":"/weɪ/","gloss":"caminho; jeito"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-06', 'lesson-survival-a2-01', 6, 'sentence', 'Do you mean tomorrow?', 'Você quer dizer amanhã?', '/duː juː miːn təˈmɑːroʊ/', '"Do you mean…?" confirma o que entendeu.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"mean","pos":"verb","ipa":"/miːn/","gloss":"significar, querer dizer"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-07', 'lesson-survival-a2-01', 7, 'sentence', 'I''m not sure I follow.', 'Não sei se estou acompanhando.', '/aɪm nɑːt ʃʊr aɪ ˈfɑːloʊ/', '"Follow" = acompanhar o raciocínio.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"follow","pos":"verb","ipa":"/ˈfɑːloʊ/","gloss":"seguir"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-08', 'lesson-survival-a2-01', 8, 'sentence', 'Can you write it down for me?', 'Pode escrever para mim?', '/kæn juː raɪt ɪt daʊn fɔːr miː/', '"Write down" = anotar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"write","pos":"verb","ipa":"/raɪt/","gloss":"escrever"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-09', 'lesson-survival-a2-01', 9, 'sentence', 'How do you say this in English?', 'Como se diz isso em inglês?', '/haʊ duː juː seɪ ðɪs ɪn ˈɪŋɡlɪʃ/', 'Aponte para o objeto e pergunte.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"English","pos":"proper noun","ipa":"/ˈɪŋɡlɪʃ/","gloss":"inglês"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-01-10', 'lesson-survival-a2-01', 10, 'sentence', 'Is there someone who speaks Portuguese?', 'Tem alguém que fala português?', '/ɪz ðɛr ˈsʌmwʌn huː spiːks ˌpɔːrtʃəˈɡiːz/', '"Someone who" + verbo.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"someone","pos":"pronoun","ipa":"/ˈsʌmwʌn/","gloss":"alguém"},{"surface":"who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"speaks","pos":"verb","ipa":"/spiːks/","gloss":"fala"},{"surface":"Portuguese","pos":"proper noun","ipa":"/ˌpɔːrtʃəˈɡiːz/","gloss":"português"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-02-01', 'lesson-survival-a2-02', 1, 'sentence', 'Sorry, can you repeat that?', 'Desculpe, pode repetir?', '/ˈsɑːri kæn juː rɪˈpiːt ðæt/', 'O pedido mais útil de todos.', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"repeat","pos":"verb","ipa":"/rɪˈpiːt/","gloss":"repetir"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-02', 'lesson-survival-a2-02', 2, 'sentence', 'One more time, please.', 'Mais uma vez, por favor.', '/wʌn mɔːr taɪm pliːz/', 'Forma curta.', '[]'::jsonb, '[{"surface":"One","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-03', 'lesson-survival-a2-02', 3, 'sentence', 'How do you spell that?', 'Como se escreve isso?', '/haʊ duː juː spɛl ðæt/', '"Spell" = soletrar.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"spell","pos":"verb","ipa":"/spɛl/","gloss":"soletrar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-04', 'lesson-survival-a2-02', 4, 'sentence', 'Is that B as in boy?', 'É B de boy?', '/ɪz ðæt biː æz ɪn bɔɪ/', '"B as in boy" confirma letras que soam parecido.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"B","pos":"noun","ipa":"/biː/","gloss":"letra B"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"boy","pos":"noun","ipa":"/bɔɪ/","gloss":"menino"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-05', 'lesson-survival-a2-02', 5, 'sentence', 'My last name is Silva, S I L V A.', 'Meu sobrenome é Silva, S I L V A.', '/maɪ læst neɪm ɪz ˈsɪlvə ɛs aɪ ɛl viː ə/', 'Soletre letra por letra.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"Silva","pos":"proper noun","ipa":"/ˈsɪlvə/","gloss":"Silva (sobrenome)"},{"surface":"S","pos":"noun","ipa":"/ɛs/","gloss":"letra S"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"L","pos":"noun","ipa":"/ɛl/","gloss":"letra L"},{"surface":"V","pos":"noun","ipa":"/viː/","gloss":"letra V"},{"surface":"A","pos":"determiner","ipa":"/ə/","gloss":"um, uma"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-06', 'lesson-survival-a2-02', 6, 'sentence', 'Sorry, I didn''t catch your name.', 'Desculpe, não peguei seu nome.', '/ˈsɑːri aɪ ˈdɪdənt kætʃ jʊr neɪm/', '"Catch" = entender, pegar (o que foi dito).', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"didn''t","pos":"auxiliary verb","ipa":"/ˈdɪdənt/","gloss":"não (passado)"},{"surface":"catch","pos":"verb","ipa":"/kætʃ/","gloss":"pegar, apanhar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-07', 'lesson-survival-a2-02', 7, 'sentence', 'Could you say the number again?', 'Pode dizer o número de novo?', '/kʊd juː seɪ ðə ˈnʌmbər əˈɡɛn/', '"Again" no fim = de novo.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-08', 'lesson-survival-a2-02', 8, 'sentence', 'Let me check I have it right.', 'Deixa eu conferir se anotei certo.', '/lɛt miː tʃɛk aɪ hæv ɪt raɪt/', '"Have it right" = ter entendido certo.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"check","pos":"verb","ipa":"/tʃɛk/","gloss":"fazer (check-in)"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-09', 'lesson-survival-a2-02', 9, 'sentence', 'Is it with a C or a K?', 'É com C ou com K?', '/ɪz ɪt wɪð ə siː ɔːr ə keɪ/', 'Pergunta útil para nomes.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"C","pos":"noun","ipa":"/siː/","gloss":"letra C"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"K","pos":"noun","ipa":"/keɪ/","gloss":"letra K"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-02-10', 'lesson-survival-a2-02', 10, 'sentence', 'Thank you for your patience.', 'Obrigado pela paciência.', '/θæŋk juː fɔːr jʊr ˈpeɪʃəns/', '"Patience" = paciência.', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"patience","pos":"noun","ipa":"/ˈpeɪʃəns/","gloss":"paciência"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-03-01', 'lesson-survival-a2-03', 1, 'sentence', 'Excuse me, can you help me?', 'Com licença, pode me ajudar?', '/ɪkˈskjuːz miː kæn juː hɛlp miː/', 'Abertura educada com estranhos.', '[]'::jsonb, '[{"surface":"Excuse","pos":"verb","ipa":"/ɪkˈskjuːz/","gloss":"desculpar (excuse me = com licença)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-02', 'lesson-survival-a2-03', 2, 'sentence', 'I''m looking for the train station.', 'Estou procurando a estação de trem.', '/aɪm ˈlʊkɪŋ fɔːr ðə treɪn ˈsteɪʃən/', '"Look for" = procurar.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"train","pos":"noun","ipa":"/treɪn/","gloss":"trem"},{"surface":"station","pos":"noun","ipa":"/ˈsteɪʃən/","gloss":"estação"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-03', 'lesson-survival-a2-03', 3, 'sentence', 'Is it far from here?', 'É longe daqui?', '/ɪz ɪt fɑːr frʌm hɪr/', '"Far from" = longe de.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"far","pos":"adjective","ipa":"/fɑːr/","gloss":"longe"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-04', 'lesson-survival-a2-03', 4, 'sentence', 'Could you show me on the map?', 'Pode me mostrar no mapa?', '/kʊd juː ʃoʊ miː ɑːn ðə mæp/', 'Mostre o celular com o mapa.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"map","pos":"noun","ipa":"/mæp/","gloss":"mapa"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-05', 'lesson-survival-a2-03', 5, 'sentence', 'Where can I buy a SIM card?', 'Onde posso comprar um chip de celular?', '/wɛr kæn aɪ baɪ ə sɪm kɑːrd/', '"SIM card" = chip de celular.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"buy","pos":"verb","ipa":"/baɪ/","gloss":"comprar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"SIM","pos":"noun","ipa":"/sɪm/","gloss":"SIM (chip)"},{"surface":"card","pos":"noun","ipa":"/kɑːrd/","gloss":"cartão"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-06', 'lesson-survival-a2-03', 6, 'sentence', 'My phone is dead. Can I use yours?', 'Meu celular descarregou. Posso usar o seu?', '/maɪ foʊn ɪz dɛd kæn aɪ juːz jʊrz/', '"Dead" = sem bateria.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"dead","pos":"adjective","ipa":"/dɛd/","gloss":"morto; sem bateria"},{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"use","pos":"verb","ipa":"/juːz/","gloss":"usar"},{"surface":"yours","pos":"pronoun","ipa":"/jʊrz/","gloss":"seu, o seu"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-07', 'lesson-survival-a2-03', 7, 'sentence', 'Is there a restroom nearby?', 'Tem banheiro por perto?', '/ɪz ðɛr ə ˈrɛstruːm ˌnɪrˈbaɪ/', '"Restroom" = banheiro público (EUA).', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"restroom","pos":"noun","ipa":"/ˈrɛstruːm/","gloss":"banheiro"},{"surface":"nearby","pos":"adverb","ipa":"/ˌnɪrˈbaɪ/","gloss":"por perto"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-08', 'lesson-survival-a2-03', 8, 'sentence', 'Where is the nearest ATM?', 'Onde fica o caixa eletrônico mais próximo?', '/wɛr ɪz ðə ˈnɪrɪst ˌeɪtiːˈɛm/', '"ATM" = caixa eletrônico.', '[]'::jsonb, '[{"surface":"Where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"nearest","pos":"adjective","ipa":"/ˈnɪrɪst/","gloss":"mais próximo"},{"surface":"ATM","pos":"noun","ipa":"/ˌeɪtiːˈɛm/","gloss":"caixa eletrônico"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-09', 'lesson-survival-a2-03', 9, 'sentence', 'Thank you so much, you saved me.', 'Muito obrigado, você me salvou.', '/θæŋk juː soʊ mʌtʃ juː seɪvd miː/', 'Agradecimento caloroso.', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"so","pos":"adverb","ipa":"/soʊ/","gloss":"tão"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"saved","pos":"verb","ipa":"/seɪvd/","gloss":"salvou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-03-10', 'lesson-survival-a2-03', 10, 'sentence', 'Sorry to bother you.', 'Desculpe incomodar.', '/ˈsɑːri tuː ˈbɑːðər juː/', '"Bother" = incomodar.', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"bother","pos":"verb","ipa":"/ˈbɑːðər/","gloss":"incomodar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-04-01', 'lesson-survival-a2-04', 1, 'sentence', 'Hello, can I speak to Mr. Brown?', 'Olá, posso falar com o Sr. Brown?', '/həˈloʊ kæn aɪ spiːk tuː ˈmɪstər braʊn/', '"Speak to" + pessoa.', '[]'::jsonb, '[{"surface":"Hello","pos":"interjection","ipa":"/həˈloʊ/","gloss":"olá"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Mr","pos":"noun","ipa":"/ˈmɪstər/","gloss":"senhor (Sr.)"},{"surface":"Brown","pos":"adjective","ipa":"/braʊn/","gloss":"marrom"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-02', 'lesson-survival-a2-04', 2, 'sentence', 'Who is calling, please?', 'Quem gostaria?', '/huː ɪz ˈkɔːlɪŋ pliːz/', 'Fala de quem atende.', '[]'::jsonb, '[{"surface":"Who","pos":"pronoun","ipa":"/huː/","gloss":"quem"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"calling","pos":"verb","ipa":"/ˈkɔːlɪŋ/","gloss":"ligando"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-03', 'lesson-survival-a2-04', 3, 'sentence', 'This is Ana speaking.', 'Aqui é a Ana.', '/ðɪs ɪz ˈænə ˈspiːkɪŋ/', 'Ao telefone use "this is".', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"Ana","pos":"proper noun","ipa":"/ˈænə/","gloss":"Ana"},{"surface":"speaking","pos":"verb","ipa":"/ˈspiːkɪŋ/","gloss":"falar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-04', 'lesson-survival-a2-04', 4, 'sentence', 'Hold on a second, please.', 'Um momento, por favor.', '/hoʊld ɑːn ə ˈsɛkənd pliːz/', '"Hold on" = aguardar.', '[]'::jsonb, '[{"surface":"Hold","pos":"verb","ipa":"/hoʊld/","gloss":"aguardar (na linha), segurar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"second","pos":"adjective","ipa":"/ˈsɛkənd/","gloss":"segundo"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-05', 'lesson-survival-a2-04', 5, 'sentence', 'He''s not here right now.', 'Ele não está agora.', '/hiːz nɑːt hɪr raɪt naʊ/', '"Right now" = neste momento.', '[]'::jsonb, '[{"surface":"He''s","pos":"pronoun","ipa":"/hiːz/","gloss":"ele é, ele está"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-06', 'lesson-survival-a2-04', 6, 'sentence', 'Can I leave a message?', 'Posso deixar um recado?', '/kæn aɪ liːv ə ˈmɛsɪdʒ/', '"Leave a message" = deixar recado.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","gloss":"mensagem"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-07', 'lesson-survival-a2-04', 7, 'sentence', 'The line is busy.', 'A linha está ocupada.', '/ðə laɪn ɪz ˈbɪzi/', '"Busy" = ocupado.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"line","pos":"noun","ipa":"/laɪn/","gloss":"linha"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"busy","pos":"adjective","ipa":"/ˈbɪzi/","gloss":"ocupado"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-08', 'lesson-survival-a2-04', 8, 'sentence', 'Sorry, the connection is bad.', 'Desculpe, a ligação está ruim.', '/ˈsɑːri ðə kəˈnɛkʃən ɪz bæd/', '"Connection" = conexão.', '[]'::jsonb, '[{"surface":"Sorry","pos":"adjective","ipa":"/ˈsɑːri/","gloss":"desculpa"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"connection","pos":"noun","ipa":"/kəˈnɛkʃən/","gloss":"conexão"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"bad","pos":"adjective","ipa":"/bæd/","gloss":"ruim"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-09', 'lesson-survival-a2-04', 9, 'sentence', 'I''ll call back later.', 'Ligo mais tarde.', '/aɪl kɔːl bæk ˈleɪtər/', '"Call back" = retornar a ligação.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-04-10', 'lesson-survival-a2-04', 10, 'sentence', 'Thanks for calling.', 'Obrigado por ligar.', '/θæŋks fɔːr ˈkɔːlɪŋ/', 'Encerramento padrão.', '[]'::jsonb, '[{"surface":"Thanks","pos":"interjection","ipa":"/θæŋks/","gloss":"obrigado, valeu"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"calling","pos":"verb","ipa":"/ˈkɔːlɪŋ/","gloss":"ligando"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-05-01', 'lesson-survival-a2-05', 1, 'sentence', 'I''d like to open an account.', 'Eu gostaria de abrir uma conta.', '/aɪd laɪk tuː ˈoʊpən ən əˈkaʊnt/', '"Open an account" = abrir conta.', '[]'::jsonb, '[{"surface":"I''d","pos":"pronoun","ipa":"/aɪd/","gloss":"eu (gostaria)"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"open","pos":"verb","ipa":"/ˈoʊpən/","gloss":"abrir"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"account","pos":"noun","ipa":"/əˈkaʊnt/","gloss":"conta (cadastro)"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-02', 'lesson-survival-a2-05', 2, 'sentence', 'What documents do I need?', 'Quais documentos eu preciso?', '/wʌt ˈdɑːkjəmənts duː aɪ niːd/', 'Pergunta essencial em qualquer balcão.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"documents","pos":"noun","ipa":"/ˈdɑːkjəmənts/","gloss":"documentos"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-03', 'lesson-survival-a2-05', 3, 'sentence', 'I want to transfer money to Brazil.', 'Quero transferir dinheiro para o Brasil.', '/aɪ wɑːnt tuː trænsˈfɜːr ˈmʌni tuː brəˈzɪl/', '"Transfer" = transferir.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"transfer","pos":"verb","ipa":"/trænsˈfɜːr/","gloss":"transferir"},{"surface":"money","pos":"noun","ipa":"/ˈmʌni/","gloss":"dinheiro"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-04', 'lesson-survival-a2-05', 4, 'sentence', 'The ATM kept my card.', 'O caixa eletrônico engoliu meu cartão.', '/ðə ˌeɪtiːˈɛm kɛpt maɪ kɑːrd/', '"Keep" = reter. Passado: "kept".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"ATM","pos":"noun","ipa":"/ˌeɪtiːˈɛm/","gloss":"caixa eletrônico"},{"surface":"kept","pos":"verb","ipa":"/kɛpt/","gloss":"guardou, manteve"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"card","pos":"noun","ipa":"/kɑːrd/","gloss":"cartão"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-05', 'lesson-survival-a2-05', 5, 'sentence', 'I forgot my PIN.', 'Esqueci a senha do cartão.', '/aɪ fərˈɡɑːt maɪ pɪn/', '"PIN" = senha numérica.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"forgot","pos":"verb","ipa":"/fərˈɡɑːt/","gloss":"esqueceu"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"PIN","pos":"noun","ipa":"/pɪn/","gloss":"senha do cartão"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-06', 'lesson-survival-a2-05', 6, 'sentence', 'Is there a fee?', 'Tem taxa?', '/ɪz ðɛr ə fiː/', '"Fee" = taxa, tarifa.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"fee","pos":"noun","ipa":"/fiː/","gloss":"taxa"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-07', 'lesson-survival-a2-05', 7, 'sentence', 'What is the exchange rate?', 'Qual é o câmbio?', '/wʌt ɪz ðə ɪksˈtʃeɪndʒ reɪt/', '"Exchange rate" = taxa de câmbio.', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"exchange","pos":"verb","ipa":"/ɪksˈtʃeɪndʒ/","gloss":"trocar"},{"surface":"rate","pos":"noun","ipa":"/reɪt/","gloss":"taxa"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-08', 'lesson-survival-a2-05', 8, 'sentence', 'I need to block my card.', 'Preciso bloquear meu cartão.', '/aɪ niːd tuː blɑːk maɪ kɑːrd/', '"Block" = bloquear.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"block","pos":"verb","ipa":"/blɑːk/","gloss":"bloquear"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"card","pos":"noun","ipa":"/kɑːrd/","gloss":"cartão"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-09', 'lesson-survival-a2-05', 9, 'sentence', 'There''s a charge I don''t recognize.', 'Tem uma cobrança que não reconheço.', '/ðɛrz ə tʃɑːrdʒ aɪ doʊnt ˈrɛkəgnaɪz/', '"Recognize" = reconhecer.', '[]'::jsonb, '[{"surface":"There''s","pos":"pronoun","ipa":"/ðɛrz/","gloss":"há, tem (there is)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"charge","pos":"noun","ipa":"/tʃɑːrdʒ/","gloss":"cobrança"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"don''t","pos":"auxiliary verb","ipa":"/doʊnt/","gloss":"não"},{"surface":"recognize","pos":"verb","ipa":"/ˈrɛkəgnaɪz/","gloss":"reconhecer"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-05-10', 'lesson-survival-a2-05', 10, 'sentence', 'Can I withdraw cash here?', 'Posso sacar dinheiro aqui?', '/kæn aɪ wɪðˈdrɔː kæʃ hɪr/', '"Withdraw" = sacar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"withdraw","pos":"verb","ipa":"/wɪðˈdrɔː/","gloss":"sacar"},{"surface":"cash","pos":"noun","ipa":"/kæʃ/","gloss":"dinheiro vivo"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-06-01', 'lesson-survival-a2-06', 1, 'sentence', 'I want to send this package to Brazil.', 'Quero enviar este pacote para o Brasil.', '/aɪ wɑːnt tuː sɛnd ðɪs ˈpækɪdʒ tuː brəˈzɪl/', '"Send to" + destino.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"want","pos":"verb","ipa":"/wɑːnt/","gloss":"querer"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-02', 'lesson-survival-a2-06', 2, 'sentence', 'How long will it take?', 'Quanto tempo vai levar?', '/haʊ lɔːŋ wɪl ɪt teɪk/', '"Take" + tempo = demorar.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-03', 'lesson-survival-a2-06', 3, 'sentence', 'How much is it to send a letter?', 'Quanto custa mandar uma carta?', '/haʊ mʌtʃ ɪz ɪt tuː sɛnd ə ˈlɛtər/', '"How much is it to" + verbo.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"letter","pos":"noun","ipa":"/ˈlɛtər/","gloss":"carta, letra"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-04', 'lesson-survival-a2-06', 4, 'sentence', 'Can I track it?', 'Posso rastrear?', '/kæn aɪ træk ɪt/', '"Track" = rastrear.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"track","pos":"noun","ipa":"/træk/","gloss":"trilha, caminho"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-05', 'lesson-survival-a2-06', 5, 'sentence', 'I need a stamp.', 'Preciso de um selo.', '/aɪ niːd ə stæmp/', '"Stamp" = selo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"stamp","pos":"noun","ipa":"/stæmp/","gloss":"selo"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-06', 'lesson-survival-a2-06', 6, 'sentence', 'Please fill out this form.', 'Por favor, preencha este formulário.', '/pliːz fɪl aʊt ðɪs fɔːrm/', '"Fill out" = preencher.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"form","pos":"noun","ipa":"/fɔːrm/","gloss":"formulário"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-07', 'lesson-survival-a2-06', 7, 'sentence', 'I''m here to pick up a package.', 'Vim retirar um pacote.', '/aɪm hɪr tuː pɪk ʌp ə ˈpækɪdʒ/', '"Pick up" = retirar, buscar.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"pick","pos":"verb","ipa":"/pɪk/","gloss":"pegar (pick up)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"package","pos":"noun","ipa":"/ˈpækɪdʒ/","gloss":"pacote"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-08', 'lesson-survival-a2-06', 8, 'sentence', 'Here is the tracking number.', 'Aqui está o código de rastreio.', '/hɪr ɪz ðə ˈtrækɪŋ ˈnʌmbər/', '"Tracking number" = código de rastreio.', '[]'::jsonb, '[{"surface":"Here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"tracking","pos":"noun","ipa":"/ˈtrækɪŋ/","gloss":"rastreamento"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-09', 'lesson-survival-a2-06', 9, 'sentence', 'Is it fragile?', 'É frágil?', '/ɪz ɪt ˈfrædʒəl/', 'Pergunta do atendente.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"fragile","pos":"adjective","ipa":"/ˈfrædʒəl/","gloss":"frágil"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-06-10', 'lesson-survival-a2-06', 10, 'sentence', 'Express or standard?', 'Expresso ou normal?', '/ɪkˈsprɛs ɔːr ˈstændərd/', 'Tipo de envio.', '[]'::jsonb, '[{"surface":"Express","pos":"adjective","ipa":"/ɪkˈsprɛs/","gloss":"expresso"},{"surface":"or","pos":"conjunction","ipa":"/ɔːr/","gloss":"ou"},{"surface":"standard","pos":"adjective","ipa":"/ˈstændərd/","gloss":"padrão"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-07-01', 'lesson-survival-a2-07', 1, 'sentence', 'Can I see your ID, please?', 'Posso ver seu documento, por favor?', '/kæn aɪ siː jʊr ˌaɪˈdiː pliːz/', '"ID" = documento de identidade.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"see","pos":"verb","ipa":"/siː/","gloss":"ver, entender"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"ID","pos":"noun","ipa":"/ˌaɪˈdiː/","gloss":"documento de identidade"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-02', 'lesson-survival-a2-07', 2, 'sentence', 'Please fill in your full name.', 'Por favor, preencha seu nome completo.', '/pliːz fɪl ɪn jʊr fʊl neɪm/', '"Full name" = nome completo.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"fill","pos":"verb","ipa":"/fɪl/","gloss":"preencher; obturar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"full","pos":"adjective","ipa":"/fʊl/","gloss":"cheio"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-03', 'lesson-survival-a2-07', 3, 'sentence', 'What''s your date of birth?', 'Qual sua data de nascimento?', '/wʌts jʊr deɪt ʌv bɜːrθ/', '"Date of birth" = data de nascimento.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"date","pos":"noun","ipa":"/deɪt/","gloss":"data"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"birth","pos":"noun","ipa":"/bɜːrθ/","gloss":"nascimento"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-04', 'lesson-survival-a2-07', 4, 'sentence', 'What''s your current address?', 'Qual seu endereço atual?', '/wʌts jʊr ˈkɜːrənt ˈædrɛs/', '"Current" = atual.', '[]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"current","pos":"adjective","ipa":"/ˈkɜːrənt/","gloss":"atual"},{"surface":"address","pos":"noun","ipa":"/ˈædrɛs/","gloss":"endereço"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-05', 'lesson-survival-a2-07', 5, 'sentence', 'Sign here, please.', 'Assine aqui, por favor.', '/saɪn hɪr pliːz/', '"Sign" = assinar.', '[]'::jsonb, '[{"surface":"Sign","pos":"verb","ipa":"/saɪn/","gloss":"assinar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-06', 'lesson-survival-a2-07', 6, 'sentence', 'Do you have a copy of your passport?', 'Você tem uma cópia do passaporte?', '/duː juː hæv ə ˈkɑːpi ʌv jʊr ˈpæspɔːrt/', '"Copy" = cópia.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"copy","pos":"noun","ipa":"/ˈkɑːpi/","gloss":"cópia"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"passport","pos":"noun","ipa":"/ˈpæspɔːrt/","gloss":"passaporte"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-07', 'lesson-survival-a2-07', 7, 'sentence', 'I need to renew my visa.', 'Preciso renovar meu visto.', '/aɪ niːd tuː rɪˈnuː maɪ ˈviːzə/', '"Renew" = renovar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"renew","pos":"verb","ipa":"/rɪˈnuː/","gloss":"renovar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"visa","pos":"noun","ipa":"/ˈviːzə/","gloss":"visto"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-08', 'lesson-survival-a2-07', 8, 'sentence', 'It will be ready in five business days.', 'Fica pronto em cinco dias úteis.', '/ɪt wɪl biː ˈrɛdi ɪn faɪv ˈbɪznəs deɪz/', '"Business days" = dias úteis.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"ready","pos":"adjective","ipa":"/ˈrɛdi/","gloss":"pronto"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"five","pos":"numeral","ipa":"/faɪv/","gloss":"cinco"},{"surface":"business","pos":"noun","ipa":"/ˈbɪznəs/","gloss":"negócio, empresa"},{"surface":"days","pos":"noun","ipa":"/deɪz/","gloss":"dias"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-09', 'lesson-survival-a2-07', 9, 'sentence', 'Please take a number and wait.', 'Por favor, pegue uma senha e aguarde.', '/pliːz teɪk ə ˈnʌmbər ænd weɪt/', '"Take a number" = pegar senha de atendimento.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"number","pos":"noun","ipa":"/ˈnʌmbər/","gloss":"número"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"wait","pos":"noun","ipa":"/weɪt/","gloss":"espera; esperar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-07-10', 'lesson-survival-a2-07', 10, 'sentence', 'Which line should I stand in?', 'Em qual fila devo ficar?', '/wɪtʃ laɪn ʃʊd aɪ stænd ɪn/', '"Stand in line" = ficar na fila.', '[]'::jsonb, '[{"surface":"Which","pos":"determiner","ipa":"/wɪtʃ/","gloss":"qual"},{"surface":"line","pos":"noun","ipa":"/laɪn/","gloss":"linha"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"stand","pos":"verb","ipa":"/stænd/","gloss":"ficar de pé; suportar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-08-01', 'lesson-survival-a2-08', 1, 'sentence', 'I lost my phone.', 'Perdi meu celular.', '/aɪ lɔːst maɪ foʊn/', 'Passado: "lost".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-02', 'lesson-survival-a2-08', 2, 'sentence', 'I think I left it on the bus.', 'Acho que deixei no ônibus.', '/aɪ θɪŋk aɪ lɛft ɪt ɑːn ðə bʌs/', '"Leave" = esquecer em algum lugar. Passado: "left".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-03', 'lesson-survival-a2-08', 3, 'sentence', 'Is there a lost and found?', 'Tem achados e perdidos?', '/ɪz ðɛr ə lɔːst ænd faʊnd/', '"Lost and found" = achados e perdidos.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"found","pos":"verb","ipa":"/faʊnd/","gloss":"achou, encontrado"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-04', 'lesson-survival-a2-08', 4, 'sentence', 'It''s a black phone with a blue case.', 'É um celular preto com capinha azul.', '/ɪts ə blæk foʊn wɪð ə bluː keɪs/', 'Descreva cor e detalhe.', '[]'::jsonb, '[{"surface":"It''s","pos":"pronoun","ipa":"/ɪts/","gloss":"é, está"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"black","pos":"adjective","ipa":"/blæk/","gloss":"preto"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"blue","pos":"adjective","ipa":"/bluː/","gloss":"azul"},{"surface":"case","pos":"noun","ipa":"/keɪs/","gloss":"capa, caso"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-05', 'lesson-survival-a2-08', 5, 'sentence', 'My key broke in the door.', 'Minha chave quebrou na porta.', '/maɪ kiː broʊk ɪn ðə dɔːr/', '"Break" passado: "broke".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"key","pos":"noun","ipa":"/kiː/","gloss":"chave"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"door","pos":"noun","ipa":"/dɔːr/","gloss":"porta"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-06', 'lesson-survival-a2-08', 6, 'sentence', 'I''m locked out.', 'Fiquei trancado do lado de fora.', '/aɪm lɑːkt aʊt/', '"Locked out" = trancado para fora.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"locked","pos":"adjective","ipa":"/lɑːkt/","gloss":"trancado"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-07', 'lesson-survival-a2-08', 7, 'sentence', 'Can you call a locksmith?', 'Pode chamar um chaveiro?', '/kæn juː kɔːl ə ˈlɑːksmɪθ/', '"Locksmith" = chaveiro.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"locksmith","pos":"noun","ipa":"/ˈlɑːksmɪθ/","gloss":"chaveiro"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-08', 'lesson-survival-a2-08', 8, 'sentence', 'My flight was changed.', 'Meu voo foi alterado.', '/maɪ flaɪt wɑːz tʃeɪndʒd/', 'Voz passiva.', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"flight","pos":"noun","ipa":"/flaɪt/","gloss":"voo"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"changed","pos":"verb","ipa":"/tʃeɪndʒd/","gloss":"mudou, mudado"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-09', 'lesson-survival-a2-08', 9, 'sentence', 'I missed my bus.', 'Perdi o ônibus.', '/aɪ mɪst maɪ bʌs/', '"Miss" = perder (transporte, horário).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"missed","pos":"verb","ipa":"/mɪst/","gloss":"perdi"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-08-10', 'lesson-survival-a2-08', 10, 'sentence', 'What should I do now?', 'O que devo fazer agora?', '/wʌt ʃʊd aɪ duː naʊ/', '"Should" = dever (conselho).', '[]'::jsonb, '[{"surface":"What","pos":"pronoun","ipa":"/wʌt/","gloss":"o que, qual"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-09-01', 'lesson-survival-a2-09', 1, 'sentence', 'I''m looking for an apartment to rent.', 'Estou procurando um apartamento para alugar.', '/aɪm ˈlʊkɪŋ fɔːr ən əˈpɑːrtmənt tuː rɛnt/', '"To rent" = para alugar.', '[]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"looking","pos":"verb","ipa":"/ˈlʊkɪŋ/","gloss":"aguardando (look forward)"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"apartment","pos":"noun","ipa":"/əˈpɑːrtmənt/","gloss":"apartamento"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"rent","pos":"verb","ipa":"/rɛnt/","gloss":"alugar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-02', 'lesson-survival-a2-09', 2, 'sentence', 'How much is the rent?', 'Quanto é o aluguel?', '/haʊ mʌtʃ ɪz ðə rɛnt/', '"Rent" = aluguel.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"rent","pos":"verb","ipa":"/rɛnt/","gloss":"alugar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-03', 'lesson-survival-a2-09', 3, 'sentence', 'Are utilities included?', 'As contas estão incluídas?', '/ɑːr juːˈtɪlətiz ɪnˈkluːdɪd/', '"Utilities" = água, luz, gás.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"utilities","pos":"noun","ipa":"/juːˈtɪlətiz/","gloss":"contas de consumo"},{"surface":"included","pos":"adjective","ipa":"/ɪnˈkluːdɪd/","gloss":"incluído"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-04', 'lesson-survival-a2-09', 4, 'sentence', 'Is there a deposit?', 'Tem caução?', '/ɪz ðɛr ə dɪˈpɑːzɪt/', '"Deposit" = caução, depósito.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"deposit","pos":"noun","ipa":"/dɪˈpɑːzɪt/","gloss":"depósito, caução"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-05', 'lesson-survival-a2-09', 5, 'sentence', 'When is the rent due?', 'Quando vence o aluguel?', '/wɛn ɪz ðə rɛnt duː/', '"Due" = com vencimento.', '[]'::jsonb, '[{"surface":"When","pos":"conjunction","ipa":"/wɛn/","gloss":"quando"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"rent","pos":"verb","ipa":"/rɛnt/","gloss":"alugar"},{"surface":"due","pos":"adjective","ipa":"/duː/","gloss":"devido (due to)"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-06', 'lesson-survival-a2-09', 6, 'sentence', 'The heater is broken.', 'O aquecedor está quebrado.', '/ðə ˈhiːtər ɪz ˈbroʊkən/', '"Heater" = aquecedor.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"heater","pos":"noun","ipa":"/ˈhiːtər/","gloss":"aquecedor"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"broken","pos":"adjective","ipa":"/ˈbroʊkən/","gloss":"quebrado"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-07', 'lesson-survival-a2-09', 7, 'sentence', 'Can you send someone to fix it?', 'Pode mandar alguém consertar?', '/kæn juː sɛnd ˈsʌmwʌn tuː fɪks ɪt/', 'Pedido ao proprietário.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"someone","pos":"pronoun","ipa":"/ˈsʌmwʌn/","gloss":"alguém"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"fix","pos":"verb","ipa":"/fɪks/","gloss":"consertar"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-08', 'lesson-survival-a2-09', 8, 'sentence', 'The electricity is off.', 'Está sem luz.', '/ðə ɪˌlɛkˈtrɪsəti ɪz ɔːf/', '"Off" = desligado.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"electricity","pos":"noun","ipa":"/ɪˌlɛkˈtrɪsəti/","gloss":"eletricidade, luz"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-09', 'lesson-survival-a2-09', 9, 'sentence', 'I need to pay the water bill.', 'Preciso pagar a conta de água.', '/aɪ niːd tuː peɪ ðə ˈwɔːtər bɪl/', '"Bill" = conta.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"water","pos":"noun","ipa":"/ˈwɔːtər/","gloss":"água"},{"surface":"bill","pos":"noun","ipa":"/bɪl/","gloss":"conta"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-09-10', 'lesson-survival-a2-09', 10, 'sentence', 'The landlord will call you.', 'O proprietário vai te ligar.', '/ðə ˈlændlɔːrd wɪl kɔːl juː/', '"Landlord" = proprietário (quem aluga).', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"landlord","pos":"noun","ipa":"/ˈlændlɔːrd/","gloss":"proprietário"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-survival-a2-10-01', 'lesson-survival-a2-10', 1, 'sentence', 'Could you speak more slowly?', 'Poderia falar mais devagar?', '/kʊd juː spiːk mɔːr ˈsloʊli/', 'Revisão: quando não entende.', '[]'::jsonb, '[{"surface":"Could","pos":"auxiliary verb","ipa":"/kʊd/","gloss":"poderia"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"speak","pos":"verb","ipa":"/spiːk/","gloss":"falar"},{"surface":"more","pos":"determiner","ipa":"/mɔːr/","gloss":"mais"},{"surface":"slowly","pos":"adverb","ipa":"/ˈsloʊli/","gloss":"devagar"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-02', 'lesson-survival-a2-10', 2, 'sentence', 'How do you spell that?', 'Como se escreve isso?', '/haʊ duː juː spɛl ðæt/', 'Revisão: soletrar.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"spell","pos":"verb","ipa":"/spɛl/","gloss":"soletrar"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-03', 'lesson-survival-a2-10', 3, 'sentence', 'Excuse me, can you help me?', 'Com licença, pode me ajudar?', '/ɪkˈskjuːz miː kæn juː hɛlp miː/', 'Revisão: pedir ajuda.', '[]'::jsonb, '[{"surface":"Excuse","pos":"verb","ipa":"/ɪkˈskjuːz/","gloss":"desculpar (excuse me = com licença)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-04', 'lesson-survival-a2-10', 4, 'sentence', 'Can I leave a message?', 'Posso deixar um recado?', '/kæn aɪ liːv ə ˈmɛsɪdʒ/', 'Revisão: telefone.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","gloss":"mensagem"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-05', 'lesson-survival-a2-10', 5, 'sentence', 'Is there a fee?', 'Tem taxa?', '/ɪz ðɛr ə fiː/', 'Revisão: banco.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"fee","pos":"noun","ipa":"/fiː/","gloss":"taxa"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-06', 'lesson-survival-a2-10', 6, 'sentence', 'Can I track it?', 'Posso rastrear?', '/kæn aɪ træk ɪt/', 'Revisão: correios.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"track","pos":"noun","ipa":"/træk/","gloss":"trilha, caminho"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-07', 'lesson-survival-a2-10', 7, 'sentence', 'Sign here, please.', 'Assine aqui, por favor.', '/saɪn hɪr pliːz/', 'Revisão: documentos.', '[]'::jsonb, '[{"surface":"Sign","pos":"verb","ipa":"/saɪn/","gloss":"assinar"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-08', 'lesson-survival-a2-10', 8, 'sentence', 'Is there a lost and found?', 'Tem achados e perdidos?', '/ɪz ðɛr ə lɔːst ænd faʊnd/', 'Revisão: objetos perdidos.', '[]'::jsonb, '[{"surface":"Is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"found","pos":"verb","ipa":"/faʊnd/","gloss":"achou, encontrado"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-09', 'lesson-survival-a2-10', 9, 'sentence', 'Are utilities included?', 'As contas estão incluídas?', '/ɑːr juːˈtɪlətiz ɪnˈkluːdɪd/', 'Revisão: moradia.', '[]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"utilities","pos":"noun","ipa":"/juːˈtɪlətiz/","gloss":"contas de consumo"},{"surface":"included","pos":"adjective","ipa":"/ɪnˈkluːdɪd/","gloss":"incluído"}]'::jsonb, NULL, NULL),
  ('unit-survival-a2-10-10', 'lesson-survival-a2-10', 10, 'sentence', 'Thank you for your patience.', 'Obrigado pela paciência.', '/θæŋk juː fɔːr jʊr ˈpeɪʃəns/', 'Revisão: fechamento educado.', '[]'::jsonb, '[{"surface":"Thank","pos":"verb","ipa":"/θæŋk/","gloss":"agradecer"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"patience","pos":"noun","ipa":"/ˈpeɪʃəns/","gloss":"paciência"}]'::jsonb, NULL, NULL)
